class NativeStartupKeyboard final {
 using P=KeyboardEnqueueTask;using D=KeyboardDequeueTask;using R=KeyboardResetTask;using M=KeyboardMapTask;using S=KeyboardScanTask;struct Job{std::variant<P,D,R,M,S>task;};
public:struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,1>CodeRanges{{{0x42c,0x54a}}};bool active()const{return depth_;}void reset(){depth_=0;steps_=0;}uint64_t steps()const{return steps_;}static bool candidate(unsigned at){return at>=0x42c&&at<0x54a;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(!depth_||boundary(jobs_[depth_-1])!=at){Job j;if(at==0x42c)j.task.emplace<P>(uint16_t(c.reg16(6)));else if(at==0x466)j.task.emplace<D>();else if(at==0x44c||at==0x452)j.task.emplace<R>(at==0x44c);else if(at==0x4aa)j.task.emplace<S>();else if(at==0x534)j.task.emplace<M>(uint16_t(c.reg16(6)));else return false;if(depth_==jobs_.size())throw std::logic_error("Native K startup keyboard capacity");jobs_[depth_++]=j;}
 auto&j=jobs_[depth_-1];std::visit([](auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,R>||std::is_same_v<T,M>||std::is_same_v<T,S>)if(t.awaiting())t.resume();},j.task);if(at!=boundary(j))throw std::logic_error("Native K startup keyboard boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(j);auto cr=credits(j,c,len);auto cost=std::visit([&](const auto&t){return t.nextClocks(cr);},j.task);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(j,c);
 std::visit([&](auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,P>)t.advanceBefore(cost,cr,[&]{c.reg16(4)=int16_t(c.read16(0xc144));val(c,c.reg16(4));return uint16_t(c.reg16(4));},[&](bool head,unsigned index,unsigned value){if(head){val(c,c.reg16(4));c.write16(int16_t(value),0xc144);}else{c.write16(int16_t(value),int(0xc148+index));val(c,c.reg16(6));}});else if constexpr(std::is_same_v<T,D>)t.advanceBefore(cost,cr,[&](bool head){if(t.stage()==D::Stage::ReadEvent){c.reg16(6)=int16_t(c.read16(int(0xc148+t.offset())));val(c,c.reg16(6));return uint16_t(c.reg16(6));}auto r=head?8:0;c.reg16(r)=int16_t(c.read16(head?0xc144:0xc146));val(c,c.reg16(r));return uint16_t(c.reg16(r));},[&](unsigned value){val(c,c.reg16(0));c.write16(int16_t(value),0xc146);});else if constexpr(std::is_same_v<T,R>)t.advanceBefore(cost,cr,[&](bool head,unsigned value){val(c,c.reg16(0));c.write16(int16_t(value),head?0xc144:0xc146);});else if constexpr(std::is_same_v<T,M>)t.advanceBefore(cost,cr,[&](unsigned index){c.reg8(14)=c.read8(int(0x84b2+index));val(c,c.reg8(14));return uint8_t(c.reg8(14));});else t.advanceBefore(cost,cr,[&](bool buttons,unsigned row){auto r=buttons?3:11;c.reg8(r)=c.read8(buttons?0xffffc7:int(0xc1c8+row));val(c,c.reg8(r));return uint8_t(c.reg8(r));},[&](S::Write field,unsigned value){if(field==S::Write::History){c.write8(int8_t(value),int(0xc1c8+t.row()));val(c,c.reg8(3));}else{val(c,c.reg8(field==S::Write::Select&&t.stage()==S::Stage::WriteSelect?10:8));c.write8(int8_t(value),field==S::Write::Direction?0xffffc5:0xffffd3);}});},j.task);
 if(c.cycles-begin!=cost)throw std::logic_error("Native K startup keyboard clocks differ");if(std::visit([](const auto&t){return t.complete();},j.task))--depth_;else if(!waiting(j))c.pc=c.makepc(boundary(j));++steps_;return true;}
private:static void val(Stage1Cpu&c,int v){midi_projection::val(c,v);}static void push(Stage1Cpu&c,unsigned r,bool word){c.setSP(c.getSP()-(word?2:4));if(word)c.write16(c.reg16(r),int(c.getSP()));else c.write32(c.reg32(r),int(c.getSP()));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}static void pop(Stage1Cpu&c,unsigned r,bool word){if(word)c.reg16(r)=int16_t(c.read16(int(c.getSP())));else c.reg32(r)=int32_t(c.read32(int(c.getSP())));c.setSP(c.getSP()+(word?2:4));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}static void dec(Stage1Cpu&c,unsigned r,bool word){int old=word?c.reg16(r):c.reg8(r),v=old-1;val(c,v);if((old&~v)&(word?0x8000:128))c.ccr|=2;if(word)c.reg16(r)=int16_t(v);else c.reg8(r)=int8_t(v);}static void inc(Stage1Cpu&c,unsigned r,unsigned amount,bool word){int old=word?c.reg16(r):c.reg8(r),v=old+int(amount);val(c,v);if((~old&v)&(word?0x8000:128))c.ccr|=2;if(word)c.reg16(r)=int16_t(v);else c.reg8(r)=int8_t(v);}
 static bool waiting(const Job&j){return std::visit([](const auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,R>||std::is_same_v<T,M>||std::is_same_v<T,S>)return t.awaiting();else return false;},j.task);}
 static unsigned boundary(const Job&j){return std::visit([](const auto&t)->unsigned{using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,P>){static constexpr unsigned a[]={0x42c,0x432,0x434,0x43a,0x43c,0x43e,0x440,0x444,0x44a,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<T,D>){static constexpr unsigned a[]={0x466,0x46a,0x470,0x476,0x478,0x47a,0x47e,0x482,0x484,0x488,0x48e,0x490,0x492,0x494,0x498,0x49e,0x4a0,0x4a4,0x4a8,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<T,R>){static constexpr unsigned a[]={0x44c,0x44e,0x452,0x454,0x456,0x45c,0x462,0x464,0};return t.stage()==R::Stage::Return&&t.initialize()?0x450:a[unsigned(t.stage())];}else if constexpr(std::is_same_v<T,M>){static constexpr unsigned a[]={0x534,0x536,0x538,0x540,0x542,0x544,0x548,0};return a[unsigned(t.stage())];}else{static constexpr unsigned a[]={0x4aa,0x4ae,0x4b2,0x4b6,0x4ba,0x4be,0x4c2,0x4c4,0x4c6,0x4cc,0x4ce,0x4d0,0x4d2,0x4d4,0x4d6,0x4da,0x4dc,0x4de,0x4e0,0x4e2,0x4e4,0x4e6,0x4e8,0x4ea,0x4ee,0x4f0,0x4f2,0x4f4,0x4f6,0x4f8,0x4fa,0x4fc,0x4fe,0x500,0x502,0x504,0x506,0x508,0x50a,0x50c,0x50e,0x510,0x512,0x514,0x516,0x518,0x51a,0x51e,0x522,0x526,0x52a,0x52e,0x532,0};return a[unsigned(t.stage())];}},j.task);}
 static unsigned bytes(const Job&j){auto at=boundary(j);if(auto*t=std::get_if<S>(&j.task)){if(t->stage()<=S::Stage::RetainEvent||t->stage()>=S::Stage::RestoreEvent&&t->stage()<=S::Stage::RestorePointer)return 4;return t->stage()==S::Stage::BindHistory?6:t->stage()==S::Stage::Delay||t->stage()==S::Stage::Bits?4:2;}switch(at){case 0x538:return 8;case 0x42c:case 0x434:case 0x444:case 0x456:case 0x45c:case 0x46a:case 0x470:case 0x488:case 0x498:return 6;case 0x440:case 0x466:case 0x47a:case 0x47e:case 0x484:case 0x494:case 0x4a0:case 0x4a4:case 0x544:return 4;default:return 2;}}
 static unsigned bus(unsigned at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=unsigned(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static FlashCredits credits(const Job&j,const Stage1Cpu&c,unsigned len){FlashCredits cr;int last=int(c.getPC()+len-1);cr.pushWord=5+bus(c.getSP()-2,2,c.writeHistory());cr.popWord=5+bus(c.getSP(),2,last);cr.pushLong=8+bus(c.getSP()-4,4,c.writeHistory());cr.popLong=8+bus(c.getSP(),4,last);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.shortCall=3+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,last);if(auto*t=std::get_if<P>(&j.task)){cr.read=bus(0xc144,2,last);cr.write=bus(t->stage()==P::Stage::WriteHead?0xc144:0xc148+t->offset(),2,c.writeHistory());}else if(auto*t=std::get_if<D>(&j.task)){cr.read=bus(t->stage()==D::Stage::ReadEvent?0xc148+t->offset():t->stage()==D::Stage::ReadTail?0xc146:0xc144,2,last);cr.write=bus(0xc146,2,c.writeHistory());}else if(auto*t=std::get_if<R>(&j.task))cr.write=bus(t->stage()==R::Stage::WriteHead?0xc144:0xc146,2,c.writeHistory());else if(auto*t=std::get_if<M>(&j.task))cr.read=bus(0x84b2+t->index(),1,last);else if(auto*t=std::get_if<S>(&j.task)){cr.read=bus(0xc1c8+t->row(),1,last);cr.write=bus(0xc1c8+t->row(),1,c.writeHistory());}return cr;}
 static void project(Job&j,Stage1Cpu&c){std::visit([&](const auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,P>){using Q=P::Stage;switch(t.stage()){case Q::Extend:c.reg32(4)=uint16_t(c.reg16(4));val(c,c.reg32(4));break;case Q::Bind:c.reg32(5)=0xc148;val(c,c.reg32(5));break;case Q::Add:c.reg32(5)=int32_t(midi_projection::arithmetic(c,uint32_t(c.reg32(5)),uint32_t(c.reg32(4)),32,false));break;case Q::Advance:inc(c,4,2,true);break;case Q::Mask:c.reg16(4)&=0x7e;val(c,c.reg16(4));break;case Q::Return:midi_projection::ret(c);break;default:break;}}
 else if constexpr(std::is_same_v<T,D>){using Q=D::Stage;switch(t.stage()){case Q::Retain:push(c,0,false);break;case Q::Compare:(void)midi_projection::arithmetic(c,uint16_t(c.reg16(0)),uint16_t(c.reg16(8)),16,true);break;case Q::Empty:c.reg16(6)=int16_t(0xff00);val(c,c.reg16(6));break;case Q::RestoreEmpty:case Q::Restore:pop(c,0,false);break;case Q::ReturnEmpty:case Q::Return:midi_projection::ret(c);break;case Q::RetainPointer:push(c,1,false);break;case Q::Bind:c.reg32(1)=0xc148;val(c,c.reg32(1));break;case Q::Extend:c.reg32(0)=uint16_t(c.reg16(0));val(c,c.reg32(0));break;case Q::Add:c.reg32(1)=int32_t(midi_projection::arithmetic(c,uint32_t(c.reg32(1)),uint32_t(c.reg32(0)),32,false));break;case Q::Advance:inc(c,0,2,true);break;case Q::Mask:c.reg16(0)&=0x7e;val(c,c.reg16(0));break;case Q::RestorePointer:pop(c,1,false);break;default:break;}}
 else if constexpr(std::is_same_v<T,R>){using Q=R::Stage;switch(t.stage()){case Q::Scan:midi_projection::call(c,0x4aa,0x44e,false);break;case Q::ClearChild:midi_projection::call(c,0x452,0x450,false);break;case Q::Retain:push(c,0,true);break;case Q::Clear:c.reg16(0)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case Q::Restore:pop(c,0,true);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
 else if constexpr(std::is_same_v<T,M>){using Q=M::Stage;switch(t.stage()){case Q::ClearPointer:c.reg32(5)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case Q::CopyIndex:c.reg8(13)=c.reg8(14);val(c,c.reg8(13));break;case Q::Compare:(void)midi_projection::arithmetic(c,uint8_t(c.reg8(14)),255,8,true);break;case Q::Enqueue:if(uint16_t(c.reg16(6))!=t.event())throw std::logic_error("K key event differs");midi_projection::call(c,0x42c,0x548,true);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
 else{using Q=S::Stage;auto stage=t.stage();if(stage<=Q::RetainEvent){constexpr unsigned r[]={0,2,3,4,5,6};push(c,r[unsigned(stage)],false);return;}if(stage>=Q::RestoreEvent&&stage<=Q::RestorePointer){constexpr unsigned r[]={6,5,4,3,2,0};pop(c,r[unsigned(stage)-unsigned(Q::RestoreEvent)],false);return;}switch(stage){case Q::Input:c.reg8(8)=0;val(c,0);break;case Q::BindHistory:c.reg32(0)=0xc1c8;val(c,c.reg32(0));break;case Q::ClearKey:c.reg8(14)=0;val(c,0);break;case Q::ClearSelect:c.reg8(10)=0;val(c,0);break;case Q::Rows:c.reg8(2)=4;val(c,4);break;case Q::RetainDelay:push(c,0,true);break;case Q::Delay:c.reg16(0)=3;val(c,3);break;case Q::DecrementDelay:dec(c,0,true);break;case Q::RestoreDelay:pop(c,0,true);break;case Q::CompareBits:c.reg8(11)^=c.reg8(3);val(c,c.reg8(11));break;case Q::Bits:c.reg16(11)=8;val(c,8);break;case Q::Shift:{unsigned v=uint16_t(c.reg16(3));c.ccr=uint8_t((c.ccr&~1)|(v&1));c.reg16(3)=int16_t(v>>1);val(c,c.reg16(3));break;}case Q::Released:c.reg8(6)=0;val(c,0);break;case Q::TestPressed:c.ccr=uint8_t((c.ccr&~4)|((uint8_t(c.reg8(11))&128)?0:4));break;case Q::Pressed:c.reg8(6)=1;val(c,1);break;case Q::RetainKey:c.reg16(14)=c.reg16(6);val(c,c.reg16(14));break;case Q::Enqueue:if(uint16_t(c.reg16(6))!=t.event())throw std::logic_error("K scanned key differs");midi_projection::call(c,0x534,0x4fe,false);break;case Q::RestoreKey:c.reg16(6)=c.reg16(14);val(c,c.reg16(6));break;case Q::AdvanceKey:inc(c,14,1,false);break;case Q::DecrementBits:dec(c,11,true);break;case Q::AdvanceUnchanged:c.reg8(14)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(14)),8,8,false));break;case Q::AdvanceSelect:c.reg8(10)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(10)),8,8,false));break;case Q::AdvanceHistory:{int old=c.reg32(0),v=old+1;val(c,v);if((~old&v)&int(0x80000000))c.ccr|=2;c.reg32(0)=v;break;}case Q::DecrementRows:dec(c,2,false);break;case Q::Release:c.reg8(8)=0x40;val(c,0x40);break;case Q::Output:c.reg8(8)=-1;val(c,-1);break;case Q::Return:midi_projection::ret(c);break;default:break;}}},j.task);}
 std::array<Job,8>jobs_{};unsigned depth_=0;uint64_t steps_=0;
};
